import csv
from datetime import datetime
from collections import defaultdict

carrier_data = defaultdict(lambda: {'TotalDelivered': 0, 'OnTimeDelivered': 0})

def parse_date(date_str):
    if not date_str:
        return None
    for fmt in ('%Y-%m-%d %H:%M:%S', '%Y-%m-%d'):
        try:
            return datetime.strptime(date_str, fmt)
        except ValueError:
            continue
    return None

with open('bookstore_orders.csv', mode='r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row.get('fulfillment_status') != 'Delivered':
            continue

        carrier = row.get('carrier_name')
        if not carrier:
            continue

        carrier_data[carrier]['TotalDelivered'] += 1

        actual_date = parse_date(row.get('actual_delivery_date'))
        estimated_date = parse_date(row.get('estimated_delivery_date'))

        if actual_date and estimated_date:
            if actual_date <= estimated_date:
                carrier_data[carrier]['OnTimeDelivered'] += 1

results = []
for carrier, data in carrier_data.items():
    total = data['TotalDelivered']
    on_time = data['OnTimeDelivered']
    otd_pct = (on_time / total * 100) if total > 0 else 0.0
    results.append({
        'CarrierName': carrier,
        'TotalDelivered': total,
        'OnTimeDelivered': on_time,
        'OnTimePct': round(otd_pct, 2)
    })

# Sort by OnTimePct descending
results.sort(key=lambda x: x['OnTimePct'], reverse=True)

# Write to CSV
with open('carrier-otd.csv', mode='w', encoding='utf-8', newline='') as f:
    writer = csv.DictWriter(f, fieldnames=['CarrierName', 'TotalDelivered', 'OnTimeDelivered', 'OnTimePct'])
    writer.writeheader()
    for row in results:
        writer.writerow(row)

import csv
from datetime import datetime
from collections import defaultdict

carrier_data = defaultdict(lambda: {'DeliveredOrders': 0, 'TotalHours': 0.0})

def parse_date(date_str):
    if not date_str:
        return None
    for fmt in ('%Y-%m-%d %H:%M:%S', '%Y-%m-%d'):
        try:
            return datetime.strptime(date_str, fmt)
        except ValueError:
            continue
    return None

with open('bookstore_orders.csv', mode='r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row.get('fulfillment_status') != 'Delivered':
            continue

        carrier = row.get('carrier_name')
        if not carrier:
            continue

        order_dt = parse_date(row.get('order_timestamp'))
        actual_dt = parse_date(row.get('actual_delivery_date'))

        if order_dt and actual_dt:
            delta = actual_dt - order_dt
            hours = delta.total_seconds() / 3600.0
            carrier_data[carrier]['DeliveredOrders'] += 1
            carrier_data[carrier]['TotalHours'] += hours

results = []
for carrier, data in carrier_data.items():
    count = data['DeliveredOrders']
    avg_hours = data['TotalHours'] / count if count > 0 else 0.0
    results.append({
        'CarrierName': carrier,
        'DeliveredOrders': count,
        'AvgDeliveryHours': round(avg_hours, 2)
    })

# Sort by AvgDeliveryHours ascending
results.sort(key=lambda x: x['AvgDeliveryHours'])

# Write to CSV
with open('carrier-delivery-time.csv', mode='w', encoding='utf-8', newline='') as f:
    writer = csv.DictWriter(f, fieldnames=['CarrierName', 'DeliveredOrders', 'AvgDeliveryHours'])
    writer.writeheader()
    for row in results:
        writer.writerow(row)

