fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0) return "∞"
    val seconds = exposureTimeNs / 1_000_000_000.0
    if (seconds >= 1.0) {
        return "${String.format("%.1f", seconds).replace(".0", "")}s"
    }
    val ms = exposureTimeNs / 1_000_000.0
    if (ms >= 1.0) {
        return "1/${String.format("%.0f", ms)}s"
    }
    val us = exposureTimeNs / 1000.0
    return "1/${String.format("%.0f", us)}s"
}

