def parse_fen(fen):
    parts = fen.split(' ')
    board_str = parts[0]
    turn = parts[1]
    board = []
    for row_str in board_str.split('/'):
        row = []
        for char in row_str:
            if char.isdigit():
                row.extend([''] * int(char))
            else:
                row.append(char)
        board.append(row)
    return board, turn

def parse_uci(move):
    r1, c1 = 7 - ord(move[0]), ord(move[1]) - ord('a')
    r2, c2 = 7 - ord(move[2]), ord(move[3]) - ord('a')
    return r1, c1, r2, c2

def to_uci(r1, c1, r2, c2):
    return f"{chr(c1 + ord('a'))}{7 - r1}{chr(c2 + ord('a'))}{7 - r2}"

def apply_move(board, move):
    r1, c1, r2, c2 = parse_uci(move)
    new_board = [row[:] for row in board]
    new_board[r2][c2] = new_board[r1][c1]
    new_board[r1][c1] = ''
    return new_board

