def perft(fen, depth):
    board, turn, castling_rights, ep_target = parse_fen(fen)
    return _perft_recursive(board, turn, castling_rights, ep_target, depth)

def _perft_recursive(board, turn, castling_rights, ep_target, depth):
    if depth == 0:
        return 1
    moves = get_pseudo_moves(board, turn, castling_rights, ep_target)
    count = 0
    for move in moves:
        new_board, next_castling, next_ep = apply_move(board, move, castling_rights, ep_target)
        next_turn = 'b' if turn == 'w' else 'w'
        count += _perft_recursive(new_board, next_turn, next_castling, next_ep, depth - 1)
    return count

